import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import PropTypes from 'prop-types';
import './style.scss';
import TextField from '@mui/material/TextField';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import Button from '@mui/material/Button';
import Register from '../../features/Auth/components/Register';

function Header(props) {
  const { user, quantity } = props;

  const [open, setOpen] = useState(false);

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };
  return (
    <header className="header">
      <nav className="nav nav--tours">
        <Link className="nav__el" to="/">
          Home
        </Link>
      </nav>
      <div className="header__logo">
        <img src="/img/NodeJS-favicon.png" alt="Natours logo" />
      </div>
      <nav className="nav nav--user">
        {user ? (
          <>
            <Link className="nav__el nav__el--logout" to="#">
              Log out
            </Link>
            <Link className="nav__el" to="/me">
              <img
                className="nav__user-img"
                src={`/img/users/${user.photo}`}
                alt={`Photo of ${user.name}`}
              />
              <span>{user.name.split(' ')[0]}</span>
            </Link>
          </>
        ) : (
          <>
            <a className="nav__el" href="/login">
              Log in
            </a>

            <Button className="nav__el nav__el--cta" onClick={handleClickOpen}>
              Sign up
            </Button>
          </>
        )}
        <a className="nav__el nav__cart" href="/cart">
          <img className="icon--cart" src="/img/cart.svg" alt="Cart" />
          <span id="cart-quantity">({quantity || 0})</span>
        </a>
      </nav>

      <Dialog
        open={open}
        onClose={(event, reason) => {
          if (reason === 'backdropClick' || reason === 'escapeKeyDown') {
            return;
          }
          handleClose();
        }}
      >
        <DialogContent>
          <Register />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
        </DialogActions>
      </Dialog>
    </header>
  );
}

Header.propTypes = {
  user: PropTypes.object,
  quantity: PropTypes.number,
};

Header.defaultProps = {
  user: null,
  quantity: 0,
};

export default Header;
